 28→// AgentRunner abstracts invoking a coding agent for e2e tests.
 29→// This follows the multi-agent pattern from cmd/entire/cli/agent/agent.go.
 30→type AgentRunner interface {
 31→	// Name returns the agent name (e.g., "claude-code", "gemini-cli")
 32→	Name() string
 33→
 34→	// IsAvailable checks if the agent CLI is installed and authenticated
 35→	IsAvailable() (bool, error)
 36→
 37→	// RunPrompt executes a prompt and returns the result
 38→	RunPrompt(ctx context.Context, workDir string, prompt string) (*AgentResult, error)
 39→
 40→	// RunPromptWithTools executes with specific allowed tools
 41→	RunPromptWithTools(ctx context.Context, workDir string, prompt string, tools []string) (*AgentResult, error)
 42→}
 43→
 44→// AgentResult holds the result of an agent invocation.
 45→type AgentResult struct {
 46→	Stdout   string
 47→	Stderr   string
 48→	ExitCode int
 49→	Duration time.Duration
 50→}
 51→
 52→// AgentRunnerConfig holds configuration for agent runners.
 53→type AgentRunnerConfig struct {
 54→	Model   string        // Model to use (e.g., "haiku" for Claude)
 55→	Timeout time.Duration // Timeout per prompt
 56→}
 57→
 58→// NewAgentRunner creates an agent runner based on the agent name.
 59→//
 60→//nolint:ireturn // factory pattern intentionally returns interface
 61→func NewAgentRunner(name string, config AgentRunnerConfig) AgentRunner {
 62→	switch name {
 63→	case AgentNameClaudeCode:
 64→		return NewClaudeCodeRunner(config)
 65→	case AgentNameGemini:
 66→		return NewGeminiCLIRunner(config)
 67→	case AgentNameFactoryAIDroid:
 68→		return NewFactoryAIDroidRunner(config)
 69→	case AgentNameOpenCode:
 70→		return NewOpenCodeRunner(config)
 71→	default:
 72→		// Return a runner that reports as unavailable
 73→		return &unavailableRunner{name: name}
 74→	}
 75→}
 76→
 77→// unavailableRunner is returned for unknown agent names.
 78→type unavailableRunner struct {
 79→	name string
 80→}
 81→
 82→func (r *unavailableRunner) Name() string { return r.name }
 83→
 84→func (r *unavailableRunner) IsAvailable() (bool, error) {
 85→	return false, fmt.Errorf("unknown agent: %s", r.name)
 86→}
