 96→// ClaudeCodeRunner implements AgentRunner for Claude Code CLI.
 97→type ClaudeCodeRunner struct {
 98→	Model        string
 99→	Timeout      time.Duration
100→	AllowedTools []string
101→}
102→
103→// NewClaudeCodeRunner creates a new Claude Code runner with the given config.
104→func NewClaudeCodeRunner(config AgentRunnerConfig) *ClaudeCodeRunner {
105→	model := config.Model
106→	if model == "" {
107→		model = os.Getenv("E2E_CLAUDE_MODEL")
108→		if model == "" {
109→			model = "haiku"
110→		}
111→	}
112→
113→	timeout := config.Timeout
114→	if timeout == 0 {
115→		if envTimeout := os.Getenv("E2E_TIMEOUT"); envTimeout != "" {
116→			if parsed, err := time.ParseDuration(envTimeout); err == nil {
117→				timeout = parsed
118→			}
119→		}
120→		if timeout == 0 {
121→			timeout = 2 * time.Minute
122→		}
123→	}
124→
125→	return &ClaudeCodeRunner{
126→		Model:        model,
127→		Timeout:      timeout,
128→		AllowedTools: []string{"Edit", "Read", "Write", "Bash", "Glob", "Grep"},
129→	}
130→}
