136→// IsAvailable checks if Claude CLI is installed and responds to --version.
137→// Note: This does NOT verify authentication status. Claude Code uses OAuth
138→// authentication (via `claude login`), not ANTHROPIC_API_KEY. If the CLI is
139→// installed but not logged in, tests will fail at RunPrompt time.
140→func (r *ClaudeCodeRunner) IsAvailable() (bool, error) {
141→	// Check if claude CLI is in PATH
142→	if _, err := exec.LookPath("claude"); err != nil {
143→		return false, fmt.Errorf("claude CLI not found in PATH: %w", err)
144→	}
145→
146→	// Check if claude is working (--version doesn't require auth)
147→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
148→	defer cancel()
149→
150→	cmd := exec.CommandContext(ctx, "claude", "--version")
151→	if err := cmd.Run(); err != nil {
152→		return false, fmt.Errorf("claude CLI not working: %w", err)
153→	}
154→
155→	return true, nil
156→}
