162→func (r *ClaudeCodeRunner) RunPromptWithTools(ctx context.Context, workDir string, prompt string, tools []string) (*AgentResult, error) {
163→	// Build command: claude --model <model> -p "<prompt>" --allowedTools <tools>
164→	args := []string{
165→		"--model", r.Model,
166→		"-p", prompt,
167→	}
168→
169→	if len(tools) > 0 {
170→		// Claude CLI expects each tool as a separate argument after --allowedTools
171→		// e.g., --allowedTools Edit Read Bash (not --allowedTools "Edit,Read,Bash")
172→		args = append(args, "--allowedTools")
173→		args = append(args, tools...)
174→	}
175→
176→	// Create context with timeout
177→	ctx, cancel := context.WithTimeout(ctx, r.Timeout)
178→	defer cancel()
179→
180→	//nolint:gosec // args are constructed from trusted config, not user input
181→	cmd := exec.CommandContext(ctx, "claude", args...)
182→	cmd.Dir = workDir
183→
184→	var stdout, stderr bytes.Buffer
185→	cmd.Stdout = &stdout
186→	cmd.Stderr = &stderr
187→
188→	start := time.Now()
189→	err := cmd.Run()
190→	duration := time.Since(start)
191→
192→	result := &AgentResult{
193→		Stdout:   stdout.String(),
194→		Stderr:   stderr.String(),
195→		Duration: duration,
196→	}
197→
198→	if err != nil {
199→		exitErr := &exec.ExitError{}
200→		if errors.As(err, &exitErr) {
201→			result.ExitCode = exitErr.ExitCode()
202→		} else {
203→			result.ExitCode = -1
204→		}
205→		//nolint:wrapcheck // error is from exec.Run, caller can check ExitCode in result
206→		return result, err
207→	}
208→
209→	result.ExitCode = 0
210→	return result, nil
211→}
