276→func (r *GeminiCLIRunner) RunPromptWithTools(ctx context.Context, workDir string, prompt string, tools []string) (*AgentResult, error) {
277→	// Build command: gemini -m <model> -p "<prompt>" --approval-mode auto_edit --allowed-tools <tools>
278→	// --approval-mode auto_edit: auto-approves edit tools (write_file, replace) while prompting for others
279→	// --allowed-tools: comma-separated list of tools that bypass confirmation (e.g., git commands)
280→	args := []string{
281→		"-m", r.Model,
282→		"-p", prompt,
283→		"--approval-mode", "auto_edit",
284→	}
285→
286→	// Add default git tools that should be allowed without confirmation
287→	defaultAllowedTools := []string{
288→		"ShellTool(git status)",
289→		"ShellTool(git add)",
290→		"ShellTool(git commit)",
291→		"ShellTool(git diff)",
292→		"ShellTool(git log)",
293→	}
294→
295→	// Merge with any additional tools passed in
296→	allTools := append(defaultAllowedTools, tools...)
297→	if len(allTools) > 0 {
298→		args = append(args, "--allowed-tools", strings.Join(allTools, ","))
299→	}
300→
301→	// Create context with timeout
302→	ctx, cancel := context.WithTimeout(ctx, r.Timeout)
303→	defer cancel()
304→
305→	//nolint:gosec // args are constructed from trusted config, not user input
306→	cmd := exec.CommandContext(ctx, "gemini", args...)
307→	cmd.Dir = workDir
308→
309→	var stdout, stderr bytes.Buffer
310→	cmd.Stdout = &stdout
311→	cmd.Stderr = &stderr
312→
313→	start := time.Now()
314→	err := cmd.Run()
315→	duration := time.Since(start)
316→
317→	result := &AgentResult{
318→		Stdout:   stdout.String(),
319→		Stderr:   stderr.String(),
320→		Duration: duration,
321→	}
322→
323→	if err != nil {
324→		exitErr := &exec.ExitError{}
325→		if errors.As(err, &exitErr) {
326→			result.ExitCode = exitErr.ExitCode()
327→		} else {
328→			result.ExitCode = -1
329→		}
330→		//nolint:wrapcheck // error is from exec.Run, caller can check ExitCode in result
331→		return result, err
332→	}
333→
334→	result.ExitCode = 0
335→	return result, nil
336→}
