399→func (r *FactoryAIDroidRunner) runPromptWithExec(ctx context.Context, workDir string, prompt string) (*AgentResult, error) {
400→	args := []string{
401→		"exec",
402→		"--cwd", workDir,
403→		"--auto", r.AutoLevel,
404→		"-o", "text",
405→	}
406→
407→	// Droid uses its own permission system (.factory/settings.json), not --enabled-tools.
408→	// E2E tests pass Claude-specific tool names that Droid doesn't recognize.
409→
410→	if r.Model != "" {
411→		args = append(args, "-m", r.Model)
412→	}
413→
414→	args = append(args, prompt)
415→
416→	ctx, cancel := context.WithTimeout(ctx, r.Timeout)
417→	defer cancel()
418→
419→	//nolint:gosec // args are constructed from trusted config, not user input
420→	cmd := exec.CommandContext(ctx, "droid", args...)
421→	cmd.Dir = workDir
422→
423→	// Prevent TTY prompts in git hooks during agent-initiated commits.
424→	// Without this, the prepare-commit-msg hook detects Droid's inherited TTY
425→	// and blocks waiting for user input on the trailer confirmation prompt.
426→	cmd.Env = append(os.Environ(),
427→		"ENTIRE_TEST_TTY=0",
428→	)
429→
430→	var stdout, stderr bytes.Buffer
431→	cmd.Stdout = &stdout
432→	cmd.Stderr = &stderr
433→
434→	start := time.Now()
435→	err := cmd.Run()
436→	duration := time.Since(start)
437→
438→	result := &AgentResult{
439→		Stdout:   stdout.String(),
440→		Stderr:   stderr.String(),
441→		Duration: duration,
442→	}
443→	if droidCreditsExhausted(result.Stdout, result.Stderr) {
444→		result.ExitCode = 1
445→		return result, errors.New("droid account credits exhausted; reload tokens at https://app.factory.ai/settings/billing")
446→	}
447→	if droidRateLimited(result.Stdout, result.Stderr) {
448→		result.ExitCode = 1
449→		return result, errors.New("droid rate limited (429 Too Many Requests); retry after a short wait")
450→	}
451→
452→	if err != nil {
453→		exitErr := &exec.ExitError{}
454→		if errors.As(err, &exitErr) {
455→			result.ExitCode = exitErr.ExitCode()
456→		} else {
457→			result.ExitCode = -1
458→		}
459→		//nolint:wrapcheck // error is from exec.Run, caller can check ExitCode in result
460→		return result, err
461→	}
462→
463→	result.ExitCode = 0
464→	return result, nil
465→}
466→
467→func droidCreditsExhausted(stdout string, stderr string) bool {
468→	lower := strings.ToLower(stdout + "\n" + stderr)
469→	return strings.Contains(lower, "ready for more? reload your tokens") ||
470→		strings.Contains(lower, "reload your tokens at https://app.factory.ai/settings/billing")
471→}
472→
473→func droidRateLimited(stdout string, stderr string) bool {
474→	lower := strings.ToLower(stdout + "\n" + stderr)
475→	return strings.Contains(lower, "error: 429") ||
476→		strings.Contains(lower, "\"code\":\"429\"") ||
477→		strings.Contains(lower, "too many requests")
478→}
